import json
N=19
base=[[0]*N for _ in range(N)]
# objects are cross center and four arms; blank center at (9,8)
objs=[((3,6),8),((4,13),4),((12,14),1),((14,3),2),((9,8),0)]
for (r,c),v in objs:
 for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
  base[r+dr][c+dc]=3
 if v:base[r][c]=v
# ray maps, separate orientation to apply vertical precedence
hor=[[0]*N for _ in range(N)]; ver=[[0]*N for _ in range(N)]
for (r,c),v in objs:
 if not v: continue
 own={(r+dr,c+dc) for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]}
 for dr,dc,field in [(0,-1,hor),(0,1,hor),(-1,0,ver),(1,0,ver)]:
  i,j=r+dr,c+dc
  while 0<=i<N and 0<=j<N:
   if base[i][j]==3 and (i,j) not in own:break
   if base[i][j]==0:field[i][j]=v
   i+=dr;j+=dc
# Horizontal-colored beams; blank object's column zero masks them; vertical colors then take precedence
out=[row[:] for row in base]
for r in range(N):
 for c in range(N):
  if base[r][c]!=0:continue
  if hor[r][c]:out[r][c]=hor[r][c]
# neutral object's vertical projection suppresses horizontal, except original 3 cells (none on column center except arms)
for (r,c),v in objs:
 if not v:
  for i in range(N):
   if base[i][c]==0:out[i][c]=0
# now overlay active colored vertical rays and centers, preserving all markers
for r in range(N):
 for c in range(N):
  if base[r][c]==0 and ver[r][c]:out[r][c]=ver[r][c]
assert len(out)==N and all(len(x)==N for x in out)
print(json.dumps({'action':'submit','grid':out},separators=(',',':')))

